require 'page-guard.php';require '../config/db_conn.php';require '../includes/attendance-schema.php';require '../includes/teacher-profile-schema.php';require '../includes/teacher-assignment-schema.php';ensureAttendanceTimeOutColumn($conn);ensureTeacherProfileColumns($conn);ensureTeacherAssignmentSchema($conn);require 'components.php';
$id=(int)($_GET['id']??0);$teacherId=(int)($_SESSION['teacher-id']??0);$assignments=teacherAssignments($conn,$teacherId);if(!$assignments){http_response_code(403);exit('Your teacher account does not have an assigned grade and section.');}$default=$assignments[0];$grade=(int)($_GET['grade']??$default['GRADE']);$section=trim($_GET['section']??$default['SECTION']);$allowed=false;foreach($assignments as $assignment)if((int)$assignment['GRADE']===$grade){$allowed=true;break;}if(!$allowed){http_response_code(404);exit('That grade is not assigned to your account.');}
$stmt=$conn->prepare('SELECT * FROM students WHERE ID=? AND SECTION=? AND GRADE=? LIMIT 1');$stmt->bind_param('isi',$id,$section,$grade);$stmt->execute();$student=$stmt->get_result()->fetch_assoc();if(!$student){http_response_code(404);exit('Student not found.');}$log=$conn->prepare('SELECT TIME_IN,TIME_OUT FROM attendance WHERE TRIM(STUDENT_ID)=TRIM(?) ORDER BY TIME_IN DESC');$log->bind_param('s',$student['STUDENT_ID']);$log->execute();$records=$log->get_result();teacherHead('Student profile');teacherShell('Student profile');
