In->format('F j, Y') ?></td><td class="px-5 py-4 text-slate-700"><?= $timeIn->format('g:i A') ?></td><td class="px-5 py-4 text-slate-700"><?= $timeOut?$timeOut->format('g:i A'):'—' ?></td><td class="px-5 py-4"><span class="rounded-full px-3 py-1 text-xs font-bold <?= attendanceStatusClass($record['TIME_IN'],$record['TIME_OUT']??null) ?>"><?= htmlspecialchars($status) ?></span></td></tr><?php endwhile;else:?><tr><td colspan="4" class="px-5 py-10 text-center text-slate-500">No attendance records found.</td></tr><?php endif; ?></tbody></table></div></section></div><?php teacherFoot(); ?>
